(function(){var selected='b';try{var saved=localStorage.getItem('ai-daily-theme');if(['a','b','c'].includes(saved))selected=saved}catch(e){}document.documentElement.dataset.theme=selected;var link=document.getElementById('theme-css');if(link){var versions={};try{versions=JSON.parse(link.dataset.versions||'{}')}catch(e){}var file='theme-'+selected+'.css';var version=versions[file];link.setAttribute('href',link.dataset.prefix+'assets/'+file+(typeof version==='string'&&/^[a-f0-9]{16}$/.test(version)?'?v='+version:''))}window.__dailyTheme=selected})();
